  let state = {version:'3.0',mode:'treasury',tab:'overview',positionDate:today,bookKind:'illustrative',portfolioKind:'illustrative',preset:'assumed-10',commonShock:10,adjustments:{},volumePct:0,budgetLimitNok:2000000,assetShocks:{Equity:-15,Bonds:-3,Cash:0,'Real assets':-10},benchmarkHedgePct:0,book:[],holdings:[],heatmapId:'',csaMode:'none',csaThreshold:0,csaMta:100000,liquidityBuffer:15000000,evidenceHorizon:'1',evidenceModel:'rw',historyCurrency:'EUR'};
  const keys = () => Object.keys(data.market).filter(c=>c!=='NOK');
