  function uiErrors(){const out=[];if(!dateValid(state.positionDate))out.push({path:'Position date',message:'Enter a valid calendar date.'});for(const [name,v,min] of [['Common FX change',state.commonShock,-99.999],...(isTreasury()?[['Forecast volume change',state.volumePct,-100],['Budget allowance',state.budgetLimitNok,0]]:[['Benchmark hedge ratio',state.benchmarkHedgePct,0]])])if(!finite(number(v))||number(v)<min)out.push({path:name,message:`Enter a finite number of at least ${min}.`});if(!isTreasury()&&number(state.benchmarkHedgePct)>100)out.push({path:'Benchmark hedge ratio',message:'Use 0% to 100%.'});for(const c of keys())if(!finite(number(state.adjustments[c]??0)))out.push({path:`${c} adjustment`,message:'Enter a finite percentage-point adjustment.'});return out;}
