  function renderScenarioDescription(){const p=(data.historicalScenarios||[]).find(p=>p.id===state.preset),s=scenario();let line=p?`OBSERVED FX REPLAY · ${p.startDate} → ${p.endDate}, applied to this book at current reference rates. Not a reconstruction of historical trading.`:`ASSUMED STRESS · ${signed(number(state.commonShock),1)}% common FX change, plus individual adjustments. No probability assigned.`;if(!isTreasury())line+=` Asset returns are separate assumptions: ${Object.entries(state.assetShocks).map(([k,v])=>`${k} ${signed(number(v),1)}%`).join('; ')}.`;else line+=` Forecast volume ${signed(number(state.volumePct),1)}%; committed amounts unchanged.`;$('scenario-provenance').textContent=line;}
