  function svgStart(w,h,title){return`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>`;}
  function barChart(id,entries,{title='',millionsScale=true,horizontal=true}={}){if(!entries.length){empty(id,'No values to display.');return;}const w=Math.max(300,$(id).clientWidth||620),row=45,left=w<420?110:160,right=w<420?58:78,top=24,bottom=35,h=top+entries.length*row+bottom,vals=entries.map(r=>r.value/(millionsScale?1e6:1)),lo=Math.min(0,...vals),hi=Math.max(0,...vals),span=hi-lo||1,min=lo-.05*span,max=hi+.1*span,x=v=>left+(v-min)/(max-min)*(w-left-right);let s=svgStart(w,h,title);for(let i=0;i<4;i++){const v=min+(max-min)*i/3;s+=`<line class="chart-rule" x1="${x(v)}" x2="${x(v)}" y1="10" y2="${h-bottom}"/><text class="chart-axis" x="${x(v)}" y="${h-10}" text-anchor="middle">${fmt(v,1)}</text>`;}s+=`<line x1="${x(0)}" x2="${x(0)}" y1="10" y2="${h-bottom}" stroke="var(--subtle)"/>`;entries.forEach((r,i)=>{const v=vals[i],y=top+i*row,xx=x(v),zero=x(0);s+=`<text x="${left-12}" y="${y+17}" text-anchor="end">${esc(r.label.length>(w<420?15:23)?r.label.slice(0,w<420?14:22)+'…':r.label)}</text><rect x="${Math.min(zero,xx)}" y="${y}" width="${Math.max(2,Math.abs(xx-zero))}" height="26" rx="3" fill="${r.color||'var(--gold)'}"><title>${esc(r.label)}: ${fmt(r.value,millionsScale?0:3)}</title></rect><text class="chart-value" x="${w-2}" y="${y+18}" text-anchor="end">${signed(v,millionsScale?2:3)}</text>`;});$(id).innerHTML=s+'</svg>';}
  function waterfall(id,start,steps,end,title){const bars=[{label:'Reference',value:start,total:true},...steps,{label:'Scenario',value:end,total:true}],w=Math.max(300,$(id).clientWidth||650),h=320,L=w<420?38:54,R=12,T=34,B=66;let running=start;const geometry=bars.map((b,i)=>{if(i===0)return{...b,a:0,b:start};if(i===bars.length-1)return{...b,a:0,b:end};const a=running;running+=b.value;return{...b,a,b:running};});const values=geometry.flatMap(b=>[b.a,b.b]),min=Math.min(0,...values),max=Math.max(0,...values),span=max-min||1,y=v=>T+(max+.1*span-v)/(1.18*span)*(h-T-B),bw=(w-L-R)/bars.length;let s=svgStart(w,h,title);for(let i=0;i<4;i++){const v=min+(max-min)*i/3;s+=`<line class="chart-rule" x1="${L}" x2="${w-R}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-axis" x="${L-8}" y="${y(v)+4}" text-anchor="end">${fmt(v/1e6,1)}</text>`;}geometry.forEach((b,i)=>{const xx=L+i*bw+10,yy=Math.min(y(b.a),y(b.b)),height=Math.abs(y(b.a)-y(b.b)),color=b.total?'var(--gold)':isTreasury()?(b.value>0?'var(--bad)':'var(--good)'):(b.value<0?'var(--bad)':'var(--good)');s+=`<rect x="${xx}" y="${yy}" width="${bw-20}" height="${Math.max(2,height)}" fill="${color}" rx="2"><title>${esc(b.label)}: ${money(b.value)}</title></rect><text class="chart-value" x="${xx+(bw-20)/2}" y="${yy-8}" text-anchor="middle">${b.total?fmt(b.value/1e6,1):signed(b.value/1e6,1)}</text><text x="${xx+(bw-20)/2}" y="${h-B+25}" text-anchor="middle">${esc(({Reference:'Start',Scenario:'End','Local assets':'Local',Interaction:'Cross'})[b.label]||b.label)}</text>`;if(i<geometry.length-1)s+=`<line x1="${xx+bw-20}" x2="${xx+bw}" y1="${y(b.b)}" y2="${y(b.b)}" stroke="var(--subtle)" stroke-dasharray="3 3"/>`;});$(id).innerHTML=s+'</svg>';}
  function timelineChart(entries){const grouped=new Map();entries.forEach(r=>{const k=r.dueDate.slice(0,7),g=grouped.get(k)||{label:k,out:0,in:0};g.out+=r.outflowsNok;g.in+=r.inflowsNok;grouped.set(k,g);});const list=[...grouped.values()].sort((a,b)=>a.label.localeCompare(b.label));if(!list.length){empty('cash-timeline','No dated flows.');return;}const w=Math.max(300,$('cash-timeline').clientWidth||620),h=310,L=48,R=15,T=25,B=60,max=Math.max(...list.flatMap(g=>[g.out,g.in]),1)*1.15,y=v=>h-B-v/max*(h-T-B),bw=(w-L-R)/list.length;let s=svgStart(w,h,'Dated settlement cash equivalents, NOK millions');for(let i=0;i<4;i++){const v=max*i/3;s+=`<line class="chart-rule" x1="${L}" x2="${w-R}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-axis" x="${L-8}" y="${y(v)+4}" text-anchor="end">${fmt(v/1e6,1)}</text>`;}list.forEach((g,i)=>{const x=L+i*bw+bw*.17,b=bw*.28;s+=`<rect x="${x}" y="${y(g.out)}" width="${b}" height="${h-B-y(g.out)}" fill="var(--gold)" rx="2"><title>Payments ${g.label}: ${money(g.out)}</title></rect><rect x="${x+b+4}" y="${y(g.in)}" width="${b}" height="${h-B-y(g.in)}" fill="var(--blue)" rx="2"><title>Receipts ${g.label}: ${money(g.in)}</title></rect><text x="${L+(i+.5)*bw}" y="${h-30}" text-anchor="middle">${esc(g.label)}</text>`;});$('cash-timeline').innerHTML=s+'</svg><div class="chart-caption"><span><i style="background:var(--gold)"></i>Cash outflows</span><span><i style="background:var(--blue)"></i>Cash inflows</span></div>';}
