  const modelShort={rw:'Random walk',ar1:'Own FX history',domestic:'Domestic rates',rates:'Relative rates',energy:'Rates + energy',risk:'Rates + risk',full:'Full model',regime:'Full + stress',ensemble:'Fixed ensemble'};
  function ciChart(entries){const el=$('evidence-ci'),w=Math.max(300,el.clientWidth||620),left=w<430?115:150,right=22,top=24,row=40,h=top+entries.length*row+38,vals=entries.flatMap(r=>r.improvement_ci||[r.improvement_vs_rw]),lo=Math.min(0,...vals),hi=Math.max(0,...vals),range=hi-lo||1,x=v=>left+(v-lo+.06*range)/(1.14*range)*(w-left-right);let s=svgStart(w,h,'Forecast error improvement and nominal 95% intervals');for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;s+=`<line class="chart-rule" x1="${x(v)}" x2="${x(v)}" y1="10" y2="${h-30}"/><text class="chart-axis" x="${x(v)}" y="${h-9}" text-anchor="middle">${fmt(v,2)}</text>`;}s+=`<line x1="${x(0)}" x2="${x(0)}" y1="10" y2="${h-30}" stroke="var(--gold)" stroke-dasharray="4 4"/>`;entries.forEach((m,i)=>{const y=top+i*row,ci=m.improvement_ci||[m.improvement_vs_rw,m.improvement_vs_rw],color=m.id===state.evidenceModel?'var(--gold)':'var(--blue)';s+=`<text x="${left-10}" y="${y+5}" text-anchor="end" style="font-size:12px">${esc(modelShort[m.id]||m.label.slice(0,18))}</text><line x1="${x(ci[0])}" x2="${x(ci[1])}" y1="${y}" y2="${y}" stroke="${color}" stroke-width="2"/><line x1="${x(ci[0])}" x2="${x(ci[0])}" y1="${y-5}" y2="${y+5}" stroke="${color}"/><line x1="${x(ci[1])}" x2="${x(ci[1])}" y1="${y-5}" y2="${y+5}" stroke="${color}"/><circle cx="${x(m.improvement_vs_rw)}" cy="${y}" r="4" fill="${color}"><title>${esc(m.label)}: ${signed(m.improvement_vs_rw,4)} pp; ${fmt(ci[0],4)} to ${fmt(ci[1],4)}</title></circle>`;});el.innerHTML=s+'</svg>';}
  function renderEvidence(){if(!research)return;const h=research.horizons[state.evidenceHorizon],models=h.models,m=models.find(x=>x.id===state.evidenceModel)||models[0];state.evidenceModel=m.id;$('evidence-model').innerHTML=models.map(x=>`<option value="${esc(x.id)}" ${x.id===m.id?'selected':''}>${esc(x.label)}</option>`).join('');barChart('evidence-mae',models.map(x=>({label:modelShort[x.id]||x.label.slice(0,20),value:x.mae,color:x.id===m.id?'var(--gold)':'var(--blue)'})),{title:'Mean absolute forecast error by model',millionsScale:false});ciChart(models.filter(x=>x.id!=='rw'));$('evidence-reading').innerHTML=`<strong>${esc(m.label)} · ${state.evidenceHorizon} month${state.evidenceHorizon==='1'?'':'s'}.</strong> ${m.n} evaluation observations; MAE ${fmt(m.mae,3)} pp. ${m.id==='rw'?'The unchanged-rate random walk is a statistical benchmark.':`Holm-adjusted p-value against random walk: ${fmt(m.p_rw_holm,3)}.`} No declared forecasting advantage is validated. Treasury policy value must be assessed using exposures, costs, limits and liquidity, not MAE alone.`;$('evidence-table').innerHTML=table(['Model','MAE, pp','Gain vs RW, pp','Nominal 95% interval','N'],models.map(x=>[esc(x.label),fmt(x.mae,3),x.id==='rw'?'Reference':signed(x.improvement_vs_rw,3),x.id==='rw'?'—':(x.improvement_ci||[]).map(v=>fmt(v,3)).join(' to '),String(x.n)]));$('evidence-coverage').innerHTML=`<h3>Historical interval reliability</h3><p><strong class="${m.interval_coverage<.8?'adverse':''}">${fmt(m.interval_coverage*100,1)}% observed coverage</strong> across ${m.interval_n} eligible intervals for the selected model. The nominal residual percentile span is 5th–95th; it does not guarantee 90% future coverage.</p><p class="context-note">For the full 6-month model, 74/107 outcomes were covered (69.2%). Model residual bands are not used as treasury loss limits in this workspace. Multiple-testing control covers 45 declared comparisons.</p>`;}
  function lineChart(id,observations,title){const w=Math.max(300,$(id).clientWidth||620),h=280,L=52,R=18,T=25,B=45;if(observations.length<2){empty(id,'Insufficient retained observations.');return;}const values=observations.map(x=>x.value),lo=Math.min(...values),hi=Math.max(...values),range=hi-lo||1,dates=observations.map(r=>Date.parse(r.date)),first=dates[0],last=dates[dates.length-1],x=d=>L+(d-first)/(last-first||1)*(w-L-R),y=v=>T+(hi+.08*range-v)/(1.16*range)*(h-T-B);let s=svgStart(w,h,title);for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;s+=`<line class="chart-rule" x1="${L}" x2="${w-R}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-axis" x="${L-8}" y="${y(v)+4}" text-anchor="end">${fmt(v,v<1?3:1)}</text>`;}let path='';observations.forEach((r,i)=>{path+=`${i?'L':'M'}${x(dates[i]).toFixed(2)},${y(r.value).toFixed(2)} `;});s+=`<path d="${path}" fill="none" stroke="var(--gold)" stroke-width="2.2"/>`;for(let i=0;i<4;i++){const j=Math.round((observations.length-1)*i/3),r=observations[j];s+=`<text class="chart-axis" x="${x(dates[j])}" y="${h-12}" text-anchor="${i===0?'start':i===3?'end':'middle'}">${esc(r.date.slice(0,7))}</text>`;}observations.forEach((r,i)=>s+=`<circle cx="${x(dates[i])}" cy="${y(r.value)}" r="4" fill="transparent"><title>${esc(r.date)}: ${fmt(r.value,5)}</title></circle>`);$(id).innerHTML=s+'</svg>';}
  function renderHistory(){const c=state.historyCurrency,list=(data.history||[]).filter(r=>r.date>='2021-01-01'&&finite(r[c])).map(r=>({date:r.date,value:r[c]}));lineChart('market-history',list,`${c}/NOK observed reference history`);}
  function renderData(){if(!data)return;$('data-stamps').innerHTML=[metric('Market observation',data.marketAsOf,state.marketImported?'Imported snapshot — not independently reverified.':'Official public reference observations.'),metric('Position date',state.positionDate,isTreasury()?state.bookKind+' treasury book':state.portfolioKind+' portfolio'),metric('Research input cutoff',research.metadata.sample_end,'Frozen historical forecasting experiment.'),metric('Research calculated',research.metadata.as_of,'Not the date the October forecast was issued.')].join('');$('market-rates').innerHTML=table(['Currency','NOK per one unit','Observation date','Source / convention'],keys().map(c=>{const q=data.market[c],u=safeUrl(q.url);return[c,fmt(q.spot,c==='JPY'?6:4),esc(q.asOf),`${u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(q.source)}</a>`:esc(q.source)}<span class="table-note">${state.marketImported?'Imported saved snapshot':q.sourceUnits&&q.sourceUnits!==1?`Normalised from a quote per ${q.sourceUnits} units`:'Per one unit'}</span>`];}));$('history-currency').innerHTML=keys().map(c=>`<option value="${c}" ${c===state.historyCurrency?'selected':''}>${c}/NOK</option>`).join('');renderHistory();$('source-facts').innerHTML=(data.facts||[]).map(f=>`<article class="source-fact"><h4>${esc(f.title)}</h4><p>${esc(f.text)}</p>${safeUrl(f.url)?`<a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">${esc(f.source)} · ${esc(f.asOf)}</a>`:''}</article>`).join('');}
  function renderInstitutionalCase(){const b=data.actuals?.nbimBridge,el=$('institutional-case');if(!el||!b)return;el.hidden=isTreasury();if(isTreasury())return;el.innerHTML=`<div class="section-heading"><div><p class="eyebrow">A REPORTED INSTITUTIONAL EXAMPLE · ${esc(b.period)}</p><h3>Investment return and NOK value are different stories.</h3></div><span class="evidence-tag observed">ACTUAL PUBLISHED FUND DATA</span></div><div class="two-column"><div><div id="actual-fund-bridge" class="chart"></div><p class="context-note">NOK billions. A reported accounting bridge, separate from the illustrative portfolio above.</p></div><div><p>NBIM reported an investment return of <strong>${fmt(b.returnPct,1)}%</strong> in ${esc(b.period)}. Its NOK accounting return was <strong>${fmt(b.investmentReturnNokBn,0)} billion</strong>, while currency translation contributed <strong>${signed(b.fxTranslationNokBn,0)} billion</strong>.</p><p>Including ${fmt(b.netFlowsNokBn,0)} billion of net flows, the fund value increased by ${fmt(b.valueChangeNokBn,0)} billion NOK. This reconciliation is not an attribution of the illustrative holdings.</p><a href="${esc(safeUrl(b.url))}" target="_blank" rel="noopener noreferrer">${esc(b.source)} · published ${esc(b.publishedAt)}</a></div></div>`;barChart('actual-fund-bridge',[{label:'Accounting return',value:b.investmentReturnNokBn,color:'var(--blue)'},{label:'FX translation',value:b.fxTranslationNokBn,color:'var(--muted)'},{label:'Net flows',value:b.netFlowsNokBn,color:'var(--blue)'},{label:'Value change',value:b.valueChangeNokBn,color:'var(--gold)'}],{title:'NBIM actual 2025 fund value bridge in NOK billions',millionsScale:false});}
